BEGIN;
LOCK TABLE consolidation_configuration_workflow,consolidation_configuration_history,consolidation_snapshot IN ACCESS EXCLUSIVE MODE;
DO $$ BEGIN IF EXISTS(SELECT 1 FROM consolidation_configuration_workflow) OR EXISTS(SELECT 1 FROM consolidation_snapshot s WHERE s.source_ref LIKE 'CONSOLIDATION_CONFIGURATION:%') THEN RAISE EXCEPTION 'Refusing to remove retained consolidation configuration evidence' USING ERRCODE='55000';END IF;END $$;
REVOKE ALL ON FUNCTION refs_consolidation_configuration_hash(uuid,uuid,uuid,text,text,jsonb,jsonb,text),refs_consolidation_configuration_transition_hash(uuid,uuid,uuid,text,bigint,text),refs_read_consolidation_configuration(uuid,uuid,uuid),refs_create_consolidation_configuration(uuid,uuid,uuid,text,text,jsonb,jsonb,text,text,text),refs_transition_consolidation_configuration(uuid,uuid,uuid,text,bigint,text,text,text) FROM refs_app;
DROP TRIGGER consolidation_configuration_workflow_protect ON consolidation_configuration_workflow;DROP TRIGGER consolidation_configuration_history_append_only ON consolidation_configuration_history;DROP FUNCTION refs_read_consolidation_configuration(uuid,uuid,uuid);DROP FUNCTION refs_transition_consolidation_configuration(uuid,uuid,uuid,text,bigint,text,text,text);DROP FUNCTION refs_create_consolidation_configuration(uuid,uuid,uuid,text,text,jsonb,jsonb,text,text,text);DROP FUNCTION refs_validate_consolidation_configuration(uuid,uuid,uuid,text,jsonb,jsonb);DROP FUNCTION refs_consolidation_configuration_transition_hash(uuid,uuid,uuid,text,bigint,text);DROP FUNCTION refs_consolidation_configuration_hash(uuid,uuid,uuid,text,text,jsonb,jsonb,text);DROP FUNCTION refs_guard_consolidation_configuration_workflow();DROP TABLE consolidation_configuration_gate;DROP TABLE consolidation_configuration_history;DROP TABLE consolidation_configuration_workflow;UPDATE permission_catalog SET active=false,effective_to=clock_timestamp(),version=version+1 WHERE permission_code LIKE 'GROUP.CONSOLIDATION.CONFIG.%';DELETE FROM runtime_human_permission_authority WHERE permission_code LIKE 'GROUP.CONSOLIDATION.CONFIG.%';COMMIT;